use vstd::prelude::*;

verus! {
    // Specification: Given n participants with attendance counts in participations,
    // and a threshold k, count how many participants have attendance
    // such that 5 - attendance >= k,
    // considering at most n participants from the front of the list,
    // and return the number of complete teams of size 3 from these eligible participants.
    //
    // The spec uses nat (natural numbers) for clarity and well-foundedness.

    spec fn eligible(attendance: nat, k: nat) -> bool {
        5 >= attendance && 5 - attendance >= k
    }

    spec fn count_eligible(slice: Seq<nat>, k: nat) -> nat {
        if slice.len() == 0 {
            0
        } else {
            let head = slice.index(0);
            let tail = slice.slice(1, slice.len());
            (if eligible(head, k) { 1 } else { 0 }) + count_eligible(tail, k)
        }
    }

    fn solve(n: u8, k: u8, participations: Vec<u8>) -> (teams: u8)
        requires
            k <= 5,
            // n is at most length of participations to avoid panics (not strictly required but practical)
            n as usize <= participations.len(),
        ensures
            teams as nat == count_eligible(
                seq![i in 0..(n as nat) => participations.get(i as usize).unwrap() as nat],
                k as nat
            ) / 3,
    {
        // Limit slice length to n
        let limit = n as usize;
        let considered = &participations[..participations.len().min(limit)];

        // Count eligible participants
        let eligible_count = considered.iter()
            .filter(|&&attendance| 5u8.saturating_sub(attendance) >= k)
            .count();

        (eligible_count / 3) as u8
    }
}
